const $=s=>document.querySelector(s);let paused=matchMedia('(prefers-reduced-motion: reduce)').matches;let selectedLayer=-1,signalStart=-9999;
const motion=$('#motion');function reflectMotion(){motion.textContent=paused?'Resume motion':'Pause motion';motion.setAttribute('aria-pressed',String(paused));document.body.classList.toggle('paused',paused);if(paused)document.querySelectorAll('video').forEach(v=>v.pause())}reflectMotion();motion.onclick=()=>{paused=!paused;reflectMotion()};
const canvas=$('#network'),ctx=canvas.getContext('2d');let nw=500,nh=246;function sizeNetwork(){nw=canvas.clientWidth;nh=canvas.clientHeight;canvas.width=nw*devicePixelRatio;canvas.height=nh*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0)}sizeNetwork();window.addEventListener('resize',sizeNetwork);
const counts=[3,5,5,2];function drawNetwork(time){ctx.clearRect(0,0,nw,nh);const layers=counts.map((n,l)=>Array.from({length:n},(_,i)=>({x:25+l*(nw-50)/3,y:nh/2+(i-(n-1)/2)*42})));layers.slice(0,-1).forEach((layer,l)=>layer.forEach((a,i)=>layers[l+1].forEach((b,j)=>{ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle=(i+j)%3===0?'#414967':'#2c3048';ctx.lineWidth=.8;ctx.stroke();if(!paused){let t=((time/2200+i*.12+j*.21-l*.28)%1+1)%1;const active=time-signalStart<2700;ctx.beginPath();ctx.arc(a.x+(b.x-a.x)*t,a.y+(b.y-a.y)*t,active?2.5:1.4,0,Math.PI*2);ctx.fillStyle=active?'#ff8459':'#8797ee88';ctx.fill()}})));layers.forEach((layer,l)=>layer.forEach((p,i)=>{const sel=selectedLayer===0&&l===0||selectedLayer===1&&(l===1||l===2)||selectedLayer===2&&l===3;ctx.shadowColor=l===3?'#fa6845':'#788aff';ctx.shadowBlur=sel?25:12;ctx.beginPath();ctx.arc(p.x,p.y,sel?8:6,0,Math.PI*2);ctx.fillStyle=l===3?'#fa805c':l===0?'#c1c9ff':'#8392fc';ctx.fill();ctx.shadowBlur=0;ctx.beginPath();ctx.arc(p.x,p.y,11,0,Math.PI*2);ctx.strokeStyle='#727ba344';ctx.stroke()}));requestAnimationFrame(drawNetwork)}requestAnimationFrame(drawNetwork);
const captions=['Input: turn information, such as an image or a sentence, into numbers the model can work with.','Hidden layers: combine numbers using learned connection strengths. Different layers can pick up different patterns.','Output: turn the final numbers into a prediction. A confident prediction can still be wrong.'];document.querySelectorAll('[data-layer]').forEach(b=>b.onclick=()=>{selectedLayer=Number(b.dataset.layer);$('#network-caption').textContent=captions[selectedLayer]});$('#signal').onclick=()=>{signalStart=performance.now();$('#network-caption').textContent=paused?'Signal path: input numbers pass through learned connections to produce a prediction. Resume motion to animate it.':'Follow the bright dots: input → learned connections → prediction. Training changes those connections.'};
const tc=$('#training'),tx=tc.getContext('2d');const points=[[.08,.18],[.14,.24],[.22,.22],[.28,.34],[.37,.33],[.43,.48],[.51,.45],[.58,.59],[.65,.6],[.72,.7],[.82,.71],[.89,.84]];let slope=-.3,bias=.85,rounds=0,trainingTimer=null;
function loss(){return Math.sqrt(points.reduce((s,[x,y])=>s+(slope*x+bias-y)**2,0)/points.length)*100}
function drawTraining(){let w=tc.clientWidth,h=tc.clientHeight;tc.width=w*devicePixelRatio;tc.height=h*devicePixelRatio;tx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);const px=x=>40+x*(w-60),py=y=>h-37-y*(h-65);tx.clearRect(0,0,w,h);tx.font='11px Arial';tx.fillStyle='#aaaabd';for(let i=0;i<=4;i++){let y=i/4;tx.beginPath();tx.moveTo(40,py(y));tx.lineTo(w-20,py(y));tx.strokeStyle='#333340';tx.stroke();tx.fillText(Math.round(y*100),7,py(y)+4)}tx.fillText('Scoops sold',40,13);tx.fillText('Cooler ← Temperature → Hotter',Math.max(40,w/2-80),h-8);tx.save();tx.beginPath();tx.rect(40,20,w-60,h-57);tx.clip();tx.beginPath();tx.moveTo(px(0),py(bias));tx.lineTo(px(1),py(slope+bias));tx.strokeStyle='#fa7956';tx.lineWidth=3;tx.stroke();for(let [x,y]of points){tx.beginPath();tx.moveTo(px(x),py(y));tx.lineTo(px(x),py(slope*x+bias));tx.strokeStyle='#7886ff44';tx.lineWidth=1;tx.stroke();tx.beginPath();tx.arc(px(x),py(y),5,0,Math.PI*2);tx.fillStyle='#9aa6ff';tx.fill()}tx.restore();$('#rounds').textContent=rounds;$('#error').textContent=loss().toFixed(1)+' scoops'}
function trainStep(){let ds=0,db=0;for(let [x,y]of points){let e=slope*x+bias-y;ds+=2*e*x/points.length;db+=2*e/points.length}slope-=.35*ds;bias-=.35*db;rounds++;drawTraining()}
$('#train').onclick=()=>{if(trainingTimer)return;let n=0;$('#train').disabled=true;function step(){trainStep();n++;if(n<10&&!paused){trainingTimer=setTimeout(step,80)}else{while(n<10){trainStep();n++}trainingTimer=null;$('#train').disabled=false;$('#training-status').textContent=rounds<40?'The error is shrinking. Train again to improve the fit.':'The line is learning the trend. Some variation remains: real data is rarely perfect.'}}step()};$('#reset').onclick=()=>{clearTimeout(trainingTimer);trainingTimer=null;slope=-.3;bias=.85;rounds=0;$('#train').disabled=false;$('#training-status').textContent='The starting line is a poor fit. Help it learn from the dots.';drawTraining()};window.addEventListener('resize',drawTraining);drawTraining();
const contexts={cat:{sentence:'The cat sat on the',words:['mat','sofa','moon'],weights:[.65,.3,.05]},space:{sentence:'The astronaut floated toward the',words:['station','moon','sofa'],weights:[.6,.36,.04]},food:{sentence:'The baker took the bread out of the',words:['oven','pan','ocean'],weights:[.82,.16,.02]}};let probs=[];function updatePrediction(){const c=contexts[$('#context').value],v=Number($('#temperature').value),t=.2+v/100*1.8;let raw=c.weights.map(p=>Math.pow(p,1/t)),sum=raw.reduce((a,b)=>a+b);probs=raw.map(p=>p/sum);$('#temperature-label').textContent=v<30?'Predictable':v<70?'Balanced':'Surprising';$('#sentence').innerHTML=c.sentence+' <span class="blank">…</span>';$('#probabilities').innerHTML=c.words.map((s,i)=>'<div class="probability"><span>'+s+'</span><div class="bar"><i style="width:'+probs[i]*100+'%"></i></div><b>'+Math.round(probs[i]*100)+'%</b></div>').join('');$('#prediction-result').textContent='Your next word is waiting. Try a prediction.'}$('#context').onchange=updatePrediction;$('#temperature').oninput=updatePrediction;$('#predict').onclick=()=>{let r=Math.random(),i=0;for(;i<probs.length-1;i++){r-=probs[i];if(r<0)break}const c=contexts[$('#context').value];$('#sentence').innerHTML=c.sentence+' <span class="blank">'+c.words[i]+'</span>';$('#prediction-result').innerHTML='Selected <b>“'+c.words[i]+'”</b> from a '+Math.round(probs[i]*100)+'% chance. Try again: sampling can choose a different word.'};updatePrediction();
document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-answer]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#quiz-feedback').textContent=b.dataset.answer==='no'?'Exactly. Confident wording is not evidence. Check the source, the facts, and the context.':'Not quite. Models can sound confident while making things up. Evidence matters more than tone.'});document.querySelectorAll('video').forEach(v=>v.addEventListener('play',()=>document.querySelectorAll('video').forEach(other=>{if(other!==v)other.pause()})));
